 App(){resetProject();}
 void resetProject(){project=Project{};project.name="Untitled Beat";project.transport.bpm=90;Track audio;audio.name="Audio 1";project.tracks.push_back(audio);Pattern pat;pat.name="Pattern 1";pat.stepCount=16;pat.stepsPerBeat=4;for(auto const&[name,key]:std::vector<std::pair<std::string,std::string>>{{"Kick","kick"},{"Snare","snare"},{"Hat","hat"}}){SampleAsset s;s.name="FLOW "+name;s.nativeKey=key;s.audio=std::make_shared<AudioBuffer>(makeNativeDrum(key,project.sampleRate));auto sid=s.id;project.samples.push_back(s);DrumLane lane;lane.name=name;lane.sampleId=sid;lane.steps.resize(16);pat.lanes.push_back(lane);}pat.lanes[0].steps[0].active=true;pat.lanes[0].steps[8].active=true;pat.lanes[1].steps[4].active=true;pat.lanes[1].steps[12].active=true;for(int i=0;i<16;i+=2){pat.lanes[2].steps[static_cast<std::size_t>(i)].active=true;pat.lanes[2].steps[static_cast<std::size_t>(i)].velocity=i%4==0?.72f:.54f;}auto pid=pat.id;project.patterns.push_back(pat);Track drums;drums.name="Drums";PatternPlacement pp;pp.patternId=pid;pp.repeats=8;drums.patternClips.push_back(pp);project.tracks.push_back(drums);}
 void publish(){engine.publish(project);}void commit(Project before,const std::string&name){undo.commit(std::move(before),project,name);publish();}
 Clip*clip(){return project.tracks.empty()||project.tracks[0].clips.empty()?nullptr:&project.tracks[0].clips[0];}const Clip*clip()const{return project.tracks.empty()||project.tracks[0].clips.empty()?nullptr:&project.tracks[0].clips[0];}
 SampleAsset*activeAudioSample(){auto*c=clip();return c?project.findSample(c->sampleId):nullptr;}const SampleAsset*activeAudioSample()const{auto*c=clip();return c?project.findSample(c->sampleId):nullptr;}
 Pattern*pattern(){return project.patterns.empty()?nullptr:&project.patterns[0];}const Pattern*pattern()const{return project.patterns.empty()?nullptr:&project.patterns[0];}
 PatternPlacement*patternPlacement(){for(auto&t:project.tracks)if(t.name!="CHOPS"&&!t.patternClips.empty())return&t.patternClips[0];return nullptr;}const PatternPlacement*patternPlacement()const{for(auto const&t:project.tracks)if(t.name!="CHOPS"&&!t.patternClips.empty())return&t.patternClips[0];return nullptr;}
 Track*chopTrack(){for(auto&t:project.tracks)if(t.name=="CHOPS")return&t;return nullptr;}const Track*chopTrack()const{for(auto const&t:project.tracks)if(t.name=="CHOPS")return&t;return nullptr;}
 PatternPlacement*chopPlacement(){auto*t=chopTrack();return t&&!t->patternClips.empty()?&t->patternClips.back():nullptr;}const PatternPlacement*chopPlacement()const{auto*t=chopTrack();return t&&!t->patternClips.empty()?&t->patternClips.back():nullptr;}
 Pattern*latestChopPattern(){if(recordPatternId)if(auto*p=project.findPattern(recordPatternId))return p;if(auto*pp=chopPlacement())return project.findPattern(pp->patternId);return nullptr;}const Pattern*latestChopPattern()const{if(recordPatternId)if(auto*p=project.findPattern(recordPatternId))return p;if(auto*pp=chopPlacement())return project.findPattern(pp->patternId);return nullptr;}
 Tick playheadTick()const{return MusicalTime::samplesToTicks(engine.playheadSamples(),project.transport.bpm,engine.sampleRate());}
 int tickToX(Tick t)const{return browserW+28+static_cast<int>((static_cast<double>(t)/kPPQ)*pxPerBeat);}Rect clipRect()const{auto*c=clip();if(!c)return{};int x=tickToX(c->startTick),ww=std::max(42,tickToX(c->startTick+c->lengthTicks)-x);return{x,audioTrackY+18,std::min(ww,W-x-14),audioTrackH-34};}
 Rect patternRect()const{auto*pp=patternPlacement();auto*p=pattern();if(!pp||!p)return{};int x=tickToX(pp->startTick),ww=std::max(44,tickToX(pp->startTick+p->lengthTicks()*std::max(1,pp->repeats))-x);return{x,patternTrackY+6,std::min(ww,W-x-14),patternTrackH-12};}
 Rect chopPatternRect()const{auto*pp=chopPlacement();auto*p=latestChopPattern();if(!pp||!p)return{};int x=tickToX(pp->startTick),ww=std::max(44,tickToX(pp->startTick+p->lengthTicks()*std::max(1,pp->repeats))-x);return{x,chopTrackY+4,std::min(ww,W-x-14),chopTrackH-8};}
 int pageStart()const{return stepPage*16;}int pageCount()const{auto*p=pattern();return p?std::max(1,(p->stepCount+15)/16):1;}Rect stepRect(int lane,int local)const{constexpr int sx=368,sw=32,gap=5,row=46;return{sx+local*(sw+gap),seqY+54+lane*row,sw,28};}Rect laneMuteRect(int lane)const{return{300,seqY+54+lane*46,26,28};}Rect laneSoloRect(int lane)const{return{330,seqY+54+lane*46,26,28};}Rect nativeDrumRect(int i)const{return{25,380+i*27,170,23};}Rect padRect(int local)const{int col=local%4,row=local/4;return{858+col*138,720+row*30,128,26};}
 int padBankCount()const{auto*s=activeAudioSample();return s?std::max(1,(static_cast<int>(s->slices.size())+15)/16):1;}int globalSliceForPad(int local)const{return padBank*16+local;}
 SampleSlice*selectedSlice(){auto*s=activeAudioSample();return s&&selectedSliceIndex>=0&&selectedSliceIndex<static_cast<int>(s->slices.size())?&s->slices[static_cast<std::size_t>(selectedSliceIndex)]:nullptr;}const SampleSlice*selectedSlice()const{auto*s=activeAudioSample();return s&&selectedSliceIndex>=0&&selectedSliceIndex<static_cast<int>(s->slices.size())?&s->slices[static_cast<std::size_t>(selectedSliceIndex)]:nullptr;}
 void clampPadState(){padBank=std::clamp(padBank,0,padBankCount()-1);auto*s=activeAudioSample();if(!s||s->slices.empty()){selectedSliceIndex=-1;lastTriggeredSlice=-1;return;}if(selectedSliceIndex<0||selectedSliceIndex>=static_cast<int>(s->slices.size()))selectedSliceIndex=std::min(padBank*16,static_cast<int>(s->slices.size())-1);}
 void setPadBank(int bank){padBank=std::clamp(bank,0,padBankCount()-1);auto*s=activeAudioSample();if(s&&!s->slices.empty())selectedSliceIndex=std::min(padBank*16,static_cast<int>(s->slices.size())-1);lastTriggeredSlice=-1;status="Pad bank "+std::to_string(padBank+1)+"/"+std::to_string(padBankCount());}
 bool sampleReferencedByChops(Id sampleId)const{for(auto const&p:project.patterns)for(auto const&ev:p.chopEvents)if(ev.sampleId==sampleId)return true;return false;}
 SampleIndex frameAtAudioX(int x)const{auto*s=activeAudioSample();auto r=clipRect();if(!s||!s->audio||r.w<=0)return 0;const double u=std::clamp(static_cast<double>(x-r.x)/static_cast<double>(r.w),0.0,1.0);return static_cast<SampleIndex>(std::llround(u*s->audio->frames()));}
 int sliceBoundaryNearX(int x,int tolerance=6)const{auto*s=activeAudioSample();auto r=clipRect();if(!s||!s->audio||s->slices.size()<2||r.w<=0)return-1;for(std::size_t i=0;i+1<s->slices.size();++i){const auto frame=s->slices[i].endFrame;const int bx=r.x+static_cast<int>((static_cast<double>(frame)/s->audio->frames())*r.w);if(std::abs(x-bx)<=tolerance)return static_cast<int>(i);}return-1;}
 void clearBeatGrid(){beatGrid=BeatGridEstimate{};beatGridSampleId=0;}
 void refreshBeatGrid(){auto*s=activeAudioSample();if(!s||!s->audio){clearBeatGrid();return;}beatGrid=estimateBeatGrid(*s->audio,55,210);beatGridSampleId=s->id;}

 void importWav(const std::filesystem::path&path){try{auto audio=std::make_shared<AudioBuffer>(WavFile::read(path));Project before=project;SampleAsset s;s.path=std::filesystem::absolute(path);s.name=path.filename().string();s.audio=audio;auto sid=s.id;project.samples.push_back(s);if(project.tracks.empty())project.tracks.push_back(Track{});project.tracks[0].name="Sample";project.tracks[0].clips.clear();Clip c;c.sampleId=sid;c.sourceLength=audio->frames();c.lengthTicks=MusicalTime::samplesToTicks(audio->frames(),project.transport.bpm,audio->sampleRate);project.tracks[0].clips.push_back(c);waveform=buildWaveform(*audio,900);padBank=0;selectedSliceIndex=-1;lastTriggeredSlice=-1;clearBeatGrid();commit(std::move(before),"Import WAV");status="Imported "+path.filename().string();}catch(const std::exception&e){status=std::string("Import failed: ")+e.what();}}
 void save(){if(recordingChops)finishChopRecording();try{ProjectSerializer::save(project,projectPath);status="Saved "+projectPath.string();}catch(const std::exception&e){status=std::string("Save failed: ")+e.what();}}
 void openProject(const std::filesystem::path&p){if(recordingChops)finishChopRecording();try{project=ProjectSerializer::load(p);projectPath=p;waveform.clear();if(auto*s=activeAudioSample();s&&s->audio)waveform=buildWaveform(*s->audio,900);selectedLane=0;selectedStep=0;stepPage=0;padBank=0;selectedSliceIndex=-1;lastTriggeredSlice=-1;recordPatternId=0;publish();clampPadState();refreshBeatGrid();status="Opened "+p.filename().string();}catch(const std::exception&e){status=std::string("Open failed: ")+e.what();}}
 void changeBpm(double delta){Project before=project;project.transport.bpm=std::clamp(project.transport.bpm+delta,20.0,300.0);commit(std::move(before),"Change BPM");}
 void setPatternLength(int count){auto*p=pattern();if(!p)return;Project before=project;p->stepCount=count;for(auto&l:p->lanes)l.steps.resize(static_cast<std::size_t>(count));stepPage=std::min(stepPage,(count-1)/16);selectedStep=std::clamp(selectedStep,0,count-1);commit(std::move(before),"Change pattern length");status=std::to_string(count)+" steps";}
 void toggleStep(int lane,int step){auto*p=pattern();if(!p||lane<0||lane>=static_cast<int>(p->lanes.size()))return;auto&v=p->lanes[static_cast<std::size_t>(lane)].steps;if(step<0||step>=static_cast<int>(v.size()))return;Project before=project;selectedLane=lane;selectedStep=step;v[static_cast<std::size_t>(step)].active=!v[static_cast<std::size_t>(step)].active;commit(std::move(before),"Toggle step");}
 void adjustSelected(float dv,float dp,int dm){auto*p=pattern();if(!p||selectedLane>=static_cast<int>(p->lanes.size()))return;auto&lane=p->lanes[static_cast<std::size_t>(selectedLane)];if(selectedStep>=static_cast<int>(lane.steps.size()))return;Project before=project;auto&st=lane.steps[static_cast<std::size_t>(selectedStep)];st.velocity=std::clamp(st.velocity+dv,0.0f,1.5f);st.probability=std::clamp(st.probability+dp,0.0f,1.0f);st.microTicks=std::clamp(st.microTicks+dm,-240,240);commit(std::move(before),"Edit step");}
 void adjustLane(float vol,float pan){auto*p=pattern();if(!p||selectedLane>=static_cast<int>(p->lanes.size()))return;Project before=project;auto&lane=p->lanes[static_cast<std::size_t>(selectedLane)];lane.volume=std::clamp(lane.volume+vol,0.0f,2.0f);lane.pan=std::clamp(lane.pan+pan,-1.0f,1.0f);commit(std::move(before),"Edit lane mixer");}
 void toggleLane(int lane,bool solo){auto*p=pattern();if(!p||lane>=static_cast<int>(p->lanes.size()))return;Project before=project;if(solo)p->lanes[static_cast<std::size_t>(lane)].solo=!p->lanes[static_cast<std::size_t>(lane)].solo;else p->lanes[static_cast<std::size_t>(lane)].mute=!p->lanes[static_cast<std::size_t>(lane)].mute;commit(std::move(before),solo?"Solo lane":"Mute lane");}
 void adjustGroove(float swing,float human){auto*p=pattern();if(!p)return;Project before=project;p->swing=std::clamp(p->swing+swing,0.0f,1.0f);p->humanize=std::clamp(p->humanize+human,0.0f,1.0f);commit(std::move(before),"Edit groove");}
 void setGroove(float swing,float human,const std::string&name){auto*p=pattern();if(!p)return;Project before=project;p->swing=swing;p->humanize=human;commit(std::move(before),"Groove preset");status=name+" groove";}
 void assignNativeDrum(int index){auto*p=pattern();if(!p||index<0||index>=static_cast<int>(nativeDrumChoices().size())||selectedLane>=static_cast<int>(p->lanes.size()))return;auto const&choice=nativeDrumChoices()[static_cast<std::size_t>(index)];Project before=project;SampleAsset*asset=nullptr;for(auto&s:project.samples)if(s.nativeKey==choice.second){asset=&s;break;}if(!asset){SampleAsset s;s.name="FLOW "+choice.first;s.nativeKey=choice.second;s.audio=std::make_shared<AudioBuffer>(makeNativeDrum(choice.second,project.sampleRate));project.samples.push_back(std::move(s));asset=&project.samples.back();}p=&project.patterns[0];p->lanes[static_cast<std::size_t>(selectedLane)].sampleId=asset->id;p->lanes[static_cast<std::size_t>(selectedLane)].name=choice.first;commit(std::move(before),"Assign native drum");status="Assigned "+choice.first;}

 void analyzeActive(){auto*s=activeAudioSample();if(!s||!s->audio){status="Import/select a WAV first";return;}Project before=project;beatGrid=estimateBeatGrid(*s->audio,55,210);beatGridSampleId=s->id;if(beatGrid.valid()){s->detectedBpm=beatGrid.bpm;s->bpmConfidence=static_cast<float>(beatGrid.confidence);}else{auto est=detectBpm(*s->audio,55,210);s->detectedBpm=est.bpm;s->bpmConfidence=static_cast<float>(est.confidence);}commit(std::move(before),"Analyze sample");status=s->detectedBpm>0?"Detected "+oneDecimal(s->detectedBpm)+" BPM | grid "+std::to_string(static_cast<int>(std::round(s->bpmConfidence*100)))+"%":"BPM not confidently detected";}
 bool canReplaceSliceMap(SampleAsset*s){if(!s||!s->audio){status="Import/select a WAV first";return false;}if(sampleReferencedByChops(s->id)){status="Slice map is referenced by a recorded take; move markers or import a new sample";return false;}return true;}
 void equalChop(int count){auto*s=activeAudioSample();if(!canReplaceSliceMap(s))return;auto ranges=makeEqualSlices(*s->audio,count);Project before=project;s->slices.clear();for(std::size_t i=0;i<ranges.size();++i){SampleSlice sl;sl.name="Slice "+std::to_string(i+1);sl.startFrame=ranges[i].startFrame;sl.endFrame=ranges[i].endFrame;s->slices.push_back(sl);}padBank=0;selectedSliceIndex=s->slices.empty()?-1:0;lastTriggeredSlice=-1;commit(std::move(before),"Equal chop");status=std::to_string(count)+" chops mapped to pads";}
 void autoChop(){auto*s=activeAudioSample();if(!canReplaceSliceMap(s))return;auto tr=detectTransients(*s->audio,.9,.08);std::vector<SampleIndex>b{0};for(auto f:tr)if(f>256&&f<s->audio->frames()-256&&b.size()<64)b.push_back(f);b.push_back(s->audio->frames());std::sort(b.begin(),b.end());b.erase(std::unique(b.begin(),b.end()),b.end());if(b.size()<3){status="Too few transients; try CHOP 8";return;}Project before=project;s->slices.clear();for(std::size_t i=0;i+1<b.size()&&i<64;++i){SampleSlice sl;sl.name="Chop "+std::to_string(i+1);sl.startFrame=b[i];sl.endFrame=b[i+1];s->slices.push_back(sl);}padBank=0;selectedSliceIndex=s->slices.empty()?-1:0;lastTriggeredSlice=-1;commit(std::move(before),"Auto chop");status="Auto Chop: "+std::to_string(s->slices.size())+" slices / "+std::to_string(padBankCount())+" banks";}
 void beatGridChop(int beatsPerSlice){auto*s=activeAudioSample();if(!canReplaceSliceMap(s))return;const auto grid=estimateBeatGrid(*s->audio,55,210);if(!grid.valid()){status="Beat grid not confident enough; use CHOP 8 or Auto Chop";return;}const auto ranges=makeBeatSlices(*s->audio,grid,beatsPerSlice);if(ranges.empty()){status="Could not build beat grid slices";return;}Project before=project;s->detectedBpm=grid.bpm;s->bpmConfidence=static_cast<float>(grid.confidence);s->slices.clear();for(std::size_t i=0;i<ranges.size();++i){SampleSlice sl;sl.name=(beatsPerSlice==1?"Beat ":"Bar ")+std::to_string(i+1);sl.startFrame=ranges[i].startFrame;sl.endFrame=ranges[i].endFrame;s->slices.push_back(sl);}beatGrid=grid;beatGridSampleId=s->id;padBank=0;selectedSliceIndex=s->slices.empty()?-1:0;lastTriggeredSlice=-1;commit(std::move(before),beatsPerSlice==1?"Chop by beat":"Chop by bar");status=(beatsPerSlice==1?"Beat Chop: ":"Bar Chop: ")+std::to_string(s->slices.size())+" slices @ "+oneDecimal(grid.bpm)+" BPM";}
 void matchBpm(){auto*c=clip();auto*s=activeAudioSample();if(!c||!s||!s->audio){status="Import/select a WAV first";return;}double source=s->detectedBpm;if(source<=0){auto est=detectBpm(*s->audio,55,210);if(!est.valid()){status="Analyze BPM first";return;}source=est.bpm;s->detectedBpm=source;s->bpmConfidence=static_cast<float>(est.confidence);}double ratio=source/project.transport.bpm;if(ratio<.5||ratio>2){status="Match ratio outside safe 0.5x-2x range";return;}if(std::abs(ratio-1)<.003){status="Sample already matches project BPM";return;}Project before=project;Id sourceId=s->id;std::string sourceName=s->name;float conf=s->bpmConfidence;auto sourceSlices=s->slices;auto stretched=std::make_shared<AudioBuffer>(matchBpmWsola(*s->audio,source,project.transport.bpm));SampleAsset derived;derived.name=sourceName+" @ "+std::to_string(static_cast<int>(std::llround(project.transport.bpm)))+" BPM";derived.sourceSampleId=sourceId;derived.timeRatio=ratio;derived.detectedBpm=project.transport.bpm;derived.bpmConfidence=conf;derived.audio=stretched;for(auto const&old:sourceSlices){SampleSlice sl=old;sl.id=nextId();sl.startFrame=static_cast<SampleIndex>(std::llround(old.startFrame*ratio));sl.endFrame=std::min<SampleIndex>(stretched->frames(),static_cast<SampleIndex>(std::llround(old.endFrame*ratio)));derived.slices.push_back(sl);}auto did=derived.id;project.samples.push_back(std::move(derived));c=clip();c->sampleId=did;c->sourceStart=0;c->sourceLength=stretched->frames();c->lengthTicks=MusicalTime::samplesToTicks(stretched->frames(),project.transport.bpm,stretched->sampleRate);waveform=buildWaveform(*stretched,900);padBank=0;selectedSliceIndex=sourceSlices.empty()?-1:0;lastTriggeredSlice=-1;commit(std::move(before),"Match sample BPM");refreshBeatGrid();status="Matched "+oneDecimal(source)+" -> "+oneDecimal(project.transport.bpm)+" BPM (pitch preserved)";}

 void startChopRecording(){auto*s=activeAudioSample();if(!s||!s->audio||s->slices.empty()){status="Create chops before recording";return;}recordBefore=project;Pattern take;take.name="Chop Take";take.stepCount=64;take.stepsPerBeat=4;recordPatternId=take.id;project.patterns.push_back(take);Track*t=chopTrack();if(!t){Track nt;nt.name="CHOPS";project.tracks.push_back(std::move(nt));t=&project.tracks.back();}recordStartTick=playheadTick();PatternPlacement pp;pp.patternId=recordPatternId;pp.startTick=recordStartTick;pp.repeats=1;t->patternClips.push_back(pp);recordingChops=true;if(!engine.isPlaying())engine.play();publish();status="REC CHOPS - play the pads";}
 void finishChopRecording(){if(!recordingChops)return;recordingChops=false;auto*p=project.findPattern(recordPatternId);if(!p||p->chopEvents.empty()){project=recordBefore;recordPatternId=0;publish();status="Empty chop take discarded";return;}const auto hits=p->chopEvents.size();undo.commit(recordBefore,project,"Record chops");recordPatternId=0;publish();status="Recorded "+std::to_string(hits)+" chop hits";}
