 bool triggerPad(int local){auto*s=activeAudioSample();const int index=globalSliceForPad(local);if(!s||!s->audio||index<0||index>=static_cast<int>(s->slices.size()))return false;auto const&sl=s->slices[static_cast<std::size_t>(index)];if(sl.endFrame<=sl.startFrame)return false;selectedSliceIndex=index;if(engine.triggerPreview(s->audio,sl.startFrame,sl.endFrame-sl.startFrame,sl.gain,sl.pan,sl.chokeGroup)){lastTriggeredSlice=index;if(recordingChops){if(auto*p=project.findPattern(recordPatternId)){const Tick captured=std::max<Tick>(0,playheadTick()-recordStartTick);ChopEvent ev;ev.recordedTick=captured;ev.tick=captured;ev.sampleId=s->id;ev.sliceId=sl.id;ev.recordedVelocity=1.0f;ev.velocity=1.0f;p->chopEvents.push_back(ev);const int need=static_cast<int>((captured*4+kPPQ-1)/kPPQ)+1;p->stepCount=std::max(p->stepCount,need);publish();}}status=(recordingChops?"REC ":"")+std::string("Pad ")+padLabels[static_cast<std::size_t>(local)]+" - "+sl.name;return true;}status="Preview queue full";return false;}
 int padIndex(KeySym ks)const{switch(ks){case XK_1:return 0;case XK_2:return 1;case XK_3:return 2;case XK_4:return 3;case XK_q:case XK_Q:return 4;case XK_w:case XK_W:return 5;case XK_e:case XK_E:return 6;case XK_r:case XK_R:return 7;case XK_a:case XK_A:return 8;case XK_s:case XK_S:return 9;case XK_d:case XK_D:return 10;case XK_f:case XK_F:return 11;case XK_z:case XK_Z:return 12;case XK_x:case XK_X:return 13;case XK_c:case XK_C:return 14;case XK_v:case XK_V:return 15;default:return-1;}}

 void drawBeatOverlay(Rect r,const SampleAsset&s,unsigned long beatColor,unsigned long downbeatColor,unsigned long muted){
    if(!s.audio||beatGridSampleId!=s.id||!beatGrid.valid()||s.audio->frames()<=0)return;
    const SampleIndex interval=std::max<SampleIndex>(1,static_cast<SampleIndex>(std::llround(static_cast<double>(s.audio->sampleRate)*60.0/beatGrid.bpm)));
    for(SampleIndex f=std::max<SampleIndex>(0,beatGrid.firstBeatFrame);f<s.audio->frames();f+=interval){int x=r.x+static_cast<int>((static_cast<double>(f)/s.audio->frames())*r.w);line(d,win,gc,x,r.y,x,r.y+r.h,beatColor);}
    if(beatGrid.downbeatConfidence>.05){for(SampleIndex f=std::max<SampleIndex>(0,beatGrid.downbeatFrame);f<s.audio->frames();f+=interval*4){int x=r.x+static_cast<int>((static_cast<double>(f)/s.audio->frames())*r.w);line(d,win,gc,x,r.y,x,r.y+r.h,downbeatColor);}}
    const std::string info="GRID "+oneDecimal(beatGrid.bpm)+"  C"+std::to_string(static_cast<int>(std::round(beatGrid.confidence*100)))+"%  D"+std::to_string(static_cast<int>(std::round(beatGrid.downbeatConfidence*100)))+"%";text(d,win,gc,r.x+8,r.y+r.h-5,info,muted);
 }

