 void handleKey(XKeyEvent&k){KeySym ks=XLookupKeysym(&k,0);bool ctrl=(k.state&ControlMask)!=0,shift=(k.state&ShiftMask)!=0;if(inputMode!=InputMode::Idle){if(ks==XK_Escape){inputMode=InputMode::Idle;input.clear();return;}if(ks==XK_Return){auto value=input;auto mode=inputMode;inputMode=InputMode::Idle;input.clear();if(mode==InputMode::ImportPath)importWav(value);else if(mode==InputMode::OpenPath)openProject(value);else renameSelectedSlice(value);return;}if(ks==XK_BackSpace){if(!input.empty())input.pop_back();return;}char buf[64]{};KeySym dummy{};int n=XLookupString(&k,buf,sizeof(buf),&dummy,nullptr);if(n>0)input.append(buf,buf+n);return;}if(ctrl&&ks==XK_s){save();return;}if(ctrl&&ks==XK_z&&!shift){if(undo.undo(project)){publish();clampPadState();refreshBeatGrid();status="Undo";}return;}if(ctrl&&shift&&(ks==XK_Z||ks==XK_z)){if(undo.redo(project)){publish();clampPadState();refreshBeatGrid();status="Redo";}return;}if(ks==XK_bracketleft){setPadBank(padBank-1);return;}if(ks==XK_bracketright){setPadBank(padBank+1);return;}if(!ctrl){int pi=padIndex(ks);if(pi>=0&&triggerPad(pi))return;}if(ks==XK_t||ks==XK_T){toggleChopRecording();return;}if(ks==XK_space){engine.isPlaying()?engine.pause():engine.play();status=engine.isPlaying()?"Playing":"Paused";}else if(ks==XK_Escape){if(recordingChops)finishChopRecording();engine.stopPreviews();engine.stop();status="Stopped";}else if(ks==XK_i){inputMode=InputMode::ImportPath;input.clear();}}
 void handleButton(XButtonEvent&e){
  auto cr=clipRect();if((e.button==1||e.button==3)&&clip()&&cr.contains(e.x,e.y)){auto*s=activeAudioSample();if(s&&s->audio){int bi=sliceBoundaryNearX(e.x);if(e.button==1&&(e.state&ShiftMask)!=0){if(sampleReferencedByChops(s->id)){status="Slice count locked by recorded take; drag markers instead";return;}Project before=project;if(insertSliceBoundary(*s,frameAtAudioX(e.x),64)){commit(std::move(before),"Insert slice marker");clampPadState();status="Inserted manual slice marker";}else status="Cannot insert marker here";return;}if(e.button==3&&bi>=0){if(sampleReferencedByChops(s->id)){status="Slice count locked by recorded take; drag markers instead";return;}Project before=project;if(removeSliceBoundary(*s,static_cast<std::size_t>(bi))){commit(std::move(before),"Remove slice marker");clampPadState();status="Removed slice marker";}return;}if(e.button==1&&bi>=0){dragKind=DragKind::SliceBoundary;dragSliceBoundary=static_cast<std::size_t>(bi);dragBefore=project;status="Dragging slice marker";return;}}}
  if(e.button!=1)return;if(play.contains(e.x,e.y)){engine.play();status="Playing";return;}if(pause.contains(e.x,e.y)){engine.pause();status="Paused";return;}if(stop.contains(e.x,e.y)){if(recordingChops)finishChopRecording();engine.stopPreviews();engine.stop();status="Stopped";return;}if(bpmMinus.contains(e.x,e.y)){changeBpm(-1);return;}if(bpmPlus.contains(e.x,e.y)){changeBpm(1);return;}if(analyzeBtn.contains(e.x,e.y)){analyzeActive();return;}if(chop8Btn.contains(e.x,e.y)){equalChop(8);return;}if(autoChopBtn.contains(e.x,e.y)){autoChop();return;}if(matchBtn.contains(e.x,e.y)){matchBpm();return;}if(recChopsBtn.contains(e.x,e.y)){toggleChopRecording();return;}if(quantizeChopsBtn.contains(e.x,e.y)){quantizeLatestChops();return;}if(beatChopBtn.contains(e.x,e.y)){beatGridChop(1);return;}if(barChopBtn.contains(e.x,e.y)){beatGridChop(4);return;}if(importBtn.contains(e.x,e.y)){inputMode=InputMode::ImportPath;input.clear();return;}if(saveBtn.contains(e.x,e.y)){save();return;}if(openBtn.contains(e.x,e.y)){inputMode=InputMode::OpenPath;input.clear();return;}if(len16.contains(e.x,e.y)){setPatternLength(16);return;}if(len32.contains(e.x,e.y)){setPatternLength(32);return;}if(len64.contains(e.x,e.y)){setPatternLength(64);return;}if(pagePrev.contains(e.x,e.y)){stepPage=std::max(0,stepPage-1);return;}if(pageNext.contains(e.x,e.y)){stepPage=std::min(pageCount()-1,stepPage+1);return;}if(swingMinus.contains(e.x,e.y)){adjustGroove(-.05f,0);return;}if(swingPlus.contains(e.x,e.y)){adjustGroove(.05f,0);return;}if(humanMinus.contains(e.x,e.y)){adjustGroove(0,-.05f);return;}if(humanPlus.contains(e.x,e.y)){adjustGroove(0,.05f);return;}if(presetStraight.contains(e.x,e.y)){setGroove(0,0,"Straight");return;}if(presetBoom.contains(e.x,e.y)){setGroove(.18f,.10f,"Boom Bap");return;}if(presetLoose.contains(e.x,e.y)){setGroove(.28f,.22f,"Loose");return;}if(velMinus.contains(e.x,e.y)){adjustSelected(-.05f,0,0);return;}if(velPlus.contains(e.x,e.y)){adjustSelected(.05f,0,0);return;}if(probMinus.contains(e.x,e.y)){adjustSelected(0,-.05f,0);return;}if(probPlus.contains(e.x,e.y)){adjustSelected(0,.05f,0);return;}if(microMinus.contains(e.x,e.y)){adjustSelected(0,0,-8);return;}if(microPlus.contains(e.x,e.y)){adjustSelected(0,0,8);return;}if(laneVolMinus.contains(e.x,e.y)){adjustLane(-.05f,0);return;}if(laneVolPlus.contains(e.x,e.y)){adjustLane(.05f,0);return;}if(lanePanMinus.contains(e.x,e.y)){adjustLane(0,-.1f);return;}if(lanePanPlus.contains(e.x,e.y)){adjustLane(0,.1f);return;}if(bankPrev.contains(e.x,e.y)){setPadBank(padBank-1);return;}if(bankNext.contains(e.x,e.y)){setPadBank(padBank+1);return;}if(chopQMinus.contains(e.x,e.y)){adjustChopQuantize(-.1f);return;}if(chopQPlus.contains(e.x,e.y)){adjustChopQuantize(.1f);return;}if(chopHMinus.contains(e.x,e.y)){adjustChopHumanize(-.1f);return;}if(chopHPlus.contains(e.x,e.y)){adjustChopHumanize(.1f);return;}if(chopGridBtn.contains(e.x,e.y)){cycleChopGrid();return;}if(chopResetBtn.contains(e.x,e.y)){resetChopEdits();return;}if(padGainMinus.contains(e.x,e.y)){adjustSelectedPad(-.05f,0,0);return;}if(padGainPlus.contains(e.x,e.y)){adjustSelectedPad(.05f,0,0);return;}if(padPanMinus.contains(e.x,e.y)){adjustSelectedPad(0,-.1f,0);return;}if(padPanPlus.contains(e.x,e.y)){adjustSelectedPad(0,.1f,0);return;}if(padChokeMinus.contains(e.x,e.y)){adjustSelectedPad(0,0,-1);return;}if(padChokePlus.contains(e.x,e.y)){adjustSelectedPad(0,0,1);return;}if(renameSliceBtn.contains(e.x,e.y)){beginRenameSlice();return;}if(stopPreviewBtn.contains(e.x,e.y)){engine.stopPreviews();status="Pad previews stopped";return;}for(int i=0;i<static_cast<int>(nativeDrumChoices().size());++i)if(nativeDrumRect(i).contains(e.x,e.y)){assignNativeDrum(i);return;}for(int i=0;i<16;++i)if(padRect(i).contains(e.x,e.y)){triggerPad(i);return;}if(auto*p=pattern()){for(int li=0;li<static_cast<int>(p->lanes.size());++li){if(laneMuteRect(li).contains(e.x,e.y)){toggleLane(li,false);return;}if(laneSoloRect(li).contains(e.x,e.y)){toggleLane(li,true);return;}for(int local=0;local<16;++local){int st=pageStart()+local;if(st<p->stepCount&&stepRect(li,local).contains(e.x,e.y)){toggleStep(li,st);return;}}}}if(clip()&&cr.contains(e.x,e.y)){dragKind=DragKind::AudioClip;dragAnchorX=e.x;dragStartTick=clip()->startTick;dragBefore=project;return;}if(patternPlacement()&&patternRect().contains(e.x,e.y)){dragKind=DragKind::PatternClip;dragAnchorX=e.x;dragStartTick=patternPlacement()->startTick;dragBefore=project;return;}if(chopPlacement()&&chopPatternRect().contains(e.x,e.y)){dragKind=DragKind::ChopPatternClip;dragAnchorX=e.x;dragStartTick=chopPlacement()->startTick;dragBefore=project;return;}}
 void handleMotion(XMotionEvent&e){if(dragKind==DragKind::Idle)return;if(dragKind==DragKind::SliceBoundary){if(auto*s=activeAudioSample())if(moveSliceBoundary(*s,dragSliceBoundary,frameAtAudioX(e.x),64))publish();return;}Tick dt=static_cast<Tick>(std::llround((e.x-dragAnchorX)/pxPerBeat*kPPQ)),raw=std::max<Tick>(0,dragStartTick+dt),snap=kPPQ/4,placed=(raw+snap/2)/snap*snap;if(dragKind==DragKind::AudioClip&&clip())clip()->startTick=placed;else if(dragKind==DragKind::PatternClip&&patternPlacement())patternPlacement()->startTick=placed;else if(dragKind==DragKind::ChopPatternClip&&chopPlacement())chopPlacement()->startTick=placed;publish();}
 void handleRelease(){if(dragKind!=DragKind::Idle){std::string name=dragKind==DragKind::AudioClip?"Move clip":(dragKind==DragKind::PatternClip?"Move pattern":(dragKind==DragKind::ChopPatternClip?"Move chop take":"Move slice marker"));undo.commit(dragBefore,project,name);publish();dragKind=DragKind::Idle;status=name;}}
 int run(int argc,char**argv){d=XOpenDisplay(nullptr);if(!d){std::cerr<<"Cannot open X display\n";return 2;}int scr=DefaultScreen(d);win=XCreateSimpleWindow(d,RootWindow(d,scr),30,30,W,H,0,0,rgb(d,16,17,20));XStoreName(d,win,"FLOWDAW - Phase 2 Smart Sampling");gc=XCreateGC(d,win,0,nullptr);XSelectInput(d,win,ExposureMask|KeyPressMask|ButtonPressMask|ButtonReleaseMask|PointerMotionMask|StructureNotifyMask);XMapWindow(d,win);bool audioOk=engine.open(project.sampleRate,256);status=audioOk?"Audio device ready":"No physical audio device; engine + preview test path active";publish();if(argc>1){std::filesystem::path p=argv[1];if(p.extension()==".flow")openProject(p);else importWav(p);}using namespace std::chrono_literals;while(running){while(XPending(d)){XEvent e;XNextEvent(d,&e);if(e.type==Expose)draw();else if(e.type==KeyPress)handleKey(e.xkey);else if(e.type==ButtonPress)handleButton(e.xbutton);else if(e.type==MotionNotify)handleMotion(e.xmotion);else if(e.type==ButtonRelease)handleRelease();else if(e.type==DestroyNotify)running=false;}draw();std::this_thread::sleep_for(16ms);}if(recordingChops)finishChopRecording();engine.close();XFreeGC(d,gc);XDestroyWindow(d,win);XCloseDisplay(d);return 0;}
